    if let Some(x) = args.sim_account { builder.add_sim_account(x); }
    builder.add_mfe_ticks(args.mfe_ticks);
    builder.add_mae_ticks(args.mae_ticks);
    builder.add_pnl_ticks(args.pnl_ticks);
    builder.add_pnl_dollars(args.pnl_dollars);
    builder.add_target_price(args.target_price);
